/** Pure controller contracts authored UNRUN; no browser/native/business proof. */
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {SPECIALIST_MODULES,GAIN_MODULES,SPECIALIST_PHASES,SPECIALIST_CHECKS,validateSpecialistReadback} from './assistant-specialist-governance-experience.mjs';
import {specialistInvocation} from './assistant-specialist-native-readback.mjs';
const id='00000000-0000-4000-8000-000000000001';
test('closed20 module lifecycle has exactlyfive genuine gain capabilities and no universal promotion',()=>{assert.equal(SPECIALIST_MODULES.length,20);assert.deepEqual(GAIN_MODULES,['org','leave','attendance','claims','performance']);assert.equal(SPECIALIST_PHASES.length,121);assert.equal(new Set(SPECIALIST_PHASES).size,121);for(const m of SPECIALIST_MODULES){assert(SPECIALIST_PHASES.includes('baseline:'+m));assert(SPECIALIST_PHASES.includes('evaluate1:'+m)&&SPECIALIST_PHASES.includes('evaluate2:'+m));assert.equal(SPECIALIST_PHASES.includes('promote:'+m),GAIN_MODULES.includes(m));assert.equal(SPECIALIST_PHASES.includes('no_gain:'+m),!GAIN_MODULES.includes(m));}assert.equal(SPECIALIST_CHECKS.length,8);});
test('readback rejects wrongscope/provider/effect state and copied posted native counts',()=>{const proof={phase:'baseline:org',providerRuns:0,nativeEffectsUnchanged:true,jobId:id,module:'org',jobKind:'specialist',changed:false,mode:'baseline',used:0};assert.equal(validateSpecialistReadback(proof,'baseline:org'),proof);for(const patch of[{providerRuns:1},{module:'payroll'},{mode:'promoted'},{nativeEffectsUnchanged:false},{changed:true},{jobId:'not-an-id'}])assert.throws(()=>validateSpecialistReadback({...proof,...patch},'baseline:org'));assert.throws(()=>specialistInvocation({phase:'baseline:org',jobId:id,score:100},'baseline:org'));assert.throws(()=>specialistInvocation({phase:'create:org',sql:'select 1'},'create:org'));});
test('actual evaluation counts must be independent complete improvements; no-gain is not PASS',()=>{const result={phase:'evaluate2:org',providerRuns:0,nativeEffectsUnchanged:true,candidateId:id,module:'org',playbook:'canonical_followup_v1',evaluations:2,passing:2};validateSpecialistReadback(result,'evaluate2:org');assert.throws(()=>validateSpecialistReadback({...result,evaluations:1},'evaluate2:org'));assert.throws(()=>validateSpecialistReadback({...result,passing:1},'evaluate2:org'));assert.throws(()=>validateSpecialistReadback({...result,phase:'evaluate2:payroll',module:'payroll'},'evaluate2:payroll'));});
test('native helper is readonly physical/current-principal source verification, never setup or mutation',()=>{const source=readFileSync(new URL('./assistant-specialist-native-readback.mjs',import.meta.url),'utf8');assert(source.includes('reopenGovernedModuleReadJobTx'));assert(source.includes('specialistReviewWorkspaceTx'));assert(source.includes('app.principal'));assert(source.includes('SET TRANSACTION READ ONLY'));assert(source.includes('isolation level read committed read only'));assert(!source.includes('createCanonicalSpecialistCandidate'));assert(!source.includes('evaluateCanonicalSpecialistCandidate'));assert(!source.includes('promoteCanonicalSpecialistCandidate'));assert(!source.includes('owner.client.end'));assert(!source.includes('process.stdout'));});
